function addRoundedPath(ctx, width, height, radius) {
    ctx.beginPath();
    ctx.moveTo(radius, 0);
    ctx.lineTo(width - radius, 0);
    ctx.quadraticCurveTo(width, 0, width, radius);
    ctx.lineTo(width, height - radius);
    ctx.quadraticCurveTo(width, height, width - radius, height);
    ctx.lineTo(radius, height);
    ctx.quadraticCurveTo(0, height, 0, height - radius);
    ctx.lineTo(0, radius);
    ctx.quadraticCurveTo(0, 0, radius, 0);
    ctx.closePath();
}

function setTextureDefaults(texture) {
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;
    texture.needsUpdate = true;
    return texture;
}

function createRoundedTexture(sourceTexture) {
    const image = sourceTexture.image || sourceTexture;
    const naturalWidth = image.naturalWidth || image.width || 420;
    const naturalHeight = image.naturalHeight || image.height || 580;
    const maxTextureSide = 700;
    const scale = Math.min(1, maxTextureSide / Math.max(naturalWidth, naturalHeight));
    const width = Math.max(1, Math.round(naturalWidth * scale));
    const height = Math.max(1, Math.round(naturalHeight * scale));
    const c = document.createElement('canvas');
    c.width = width;
    c.height = height;
    const ctx = c.getContext('2d');

    const radius = Math.round(Math.min(width, height) * 0.08);
    addRoundedPath(ctx, width, height, radius);
    ctx.clip();
    ctx.drawImage(image, 0, 0, width, height);

    ctx.lineWidth = Math.max(2, Math.round(Math.min(width, height) * 0.012));
    ctx.strokeStyle = 'rgba(235,235,235,0.12)';
    addRoundedPath(ctx, width, height, radius);
    ctx.stroke();

    return setTextureDefaults(new THREE.CanvasTexture(c));
}

function createImageTexture(image) {
    const texture = new THREE.Texture(image);
    return setTextureDefaults(texture);
}

function createFallbackTexture(index) {
    const width = 420;
    const height = 580;
    const c = document.createElement('canvas');
    c.width = width;
    c.height = height;
    const ctx = c.getContext('2d');

    const radius = Math.round(Math.min(width, height) * 0.08);
    addRoundedPath(ctx, width, height, radius);
    ctx.clip();

    const hueA = (index * 37) % 360;
    const hueB = (hueA + 80) % 360;
    const gradient = ctx.createLinearGradient(0, 0, width, height);
    gradient.addColorStop(0, `hsl(${hueA} 24% 28%)`);
    gradient.addColorStop(1, `hsl(${hueB} 30% 12%)`);
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);

    ctx.globalAlpha = 0.28;
    for (let i = 0; i < 4; i += 1) {
        const r = 60 + i * 24;
        const x = (width * (0.18 + i * 0.19)) % width;
        const y = (height * (0.2 + i * 0.17)) % height;
        const blob = ctx.createRadialGradient(x, y, 4, x, y, r);
        blob.addColorStop(0, `hsla(${(hueA + i * 24) % 360} 42% 72% / 0.9)`);
        blob.addColorStop(1, 'transparent');
        ctx.fillStyle = blob;
        ctx.fillRect(0, 0, width, height);
    }

    ctx.globalAlpha = 1;
    ctx.lineWidth = Math.max(2, Math.round(Math.min(width, height) * 0.012));
    ctx.strokeStyle = 'rgba(235,235,235,0.14)';
    addRoundedPath(ctx, width, height, radius);
    ctx.stroke();

    return setTextureDefaults(new THREE.CanvasTexture(c));
}

function createVortexSystem() {
    const panel = document.getElementById('vortex');
    const canvas = document.getElementById('vortexCanvas');
    const fallback = document.getElementById('vortexFallback');

    const isMobileViewport = window.innerWidth <= 900;
    const CONFIG = {
        // mobile first-section vertical redistribution
        cardCount: isMobileViewport ? 5 : 8,
        cardWidth: 1.1,
        cardHeight: 1.6,
        vortexCenterX: 0,
        // mobile first section composition fix
        vortexCenterY: isMobileViewport ? 0.0 : 0.01,
        startRadius: isMobileViewport ? 3.0 : 4.8,
        endRadius: isMobileViewport ? 2.15 : 3.35,
        coreRadius: 0.14,
        radiusOffsetRange: isMobileViewport ? 0.06 : 0.1,
        bandThickness: isMobileViewport ? 0.06 : 0.09,
        bandYOffset: isMobileViewport ? 0.11 : 0.06,
        zNear: 1.4,
        zDeep: -14.5,
        spiralTurns: 2.3,
        rotationTurns: 0.35,
        trackOffsetMin: isMobileViewport ? 0.0 : 0.08,
        trackOffsetMax: isMobileViewport ? 0.4 : 0.24,
        pullSpeedMin: 0.97,
        pullSpeedMax: 1.01,
        trailCount: isMobileViewport ? 1 : 3,
        trailStep: 0.06,
        trailDepthStep: 0.28,
        dragSensitivity: 0.0014,
        maxInteractionOffset: 0.34,
        depthNear: isMobileViewport ? 7.1 : 8.0,
        depthFar: isMobileViewport ? 20.0 : 22.0,
        scaleMin: isMobileViewport ? 0.64 : 0.56,
        scaleMax: isMobileViewport ? 1.16 : 1.03,
        nearOpacity: 0.98,
        farOpacity: isMobileViewport ? 0.42 : 0.36,
    };

    const viewVec = new THREE.Vector3();
    const cards = [];

    let scene;
    let camera;
    let renderer;
    let ringGroup;
    let initialized = false;
    let running = false;
    let rafId = 0;
    let isDragging = false;
    let lastPointerX = 0;
    let interactionOffset = 0;
    let interactionTarget = 0;
    let depthNear = 0;
    let depthFar = 1;

    function init() {
        scene = new THREE.Scene();
        camera = new THREE.PerspectiveCamera(46, panel.clientWidth / panel.clientHeight, 0.1, 120);
        camera.position.set(0, 0, 9.4);

        renderer = new THREE.WebGLRenderer({
            canvas,
            antialias: true,
            alpha: true,
            powerPreference: 'high-performance',
        });
        renderer.setSize(panel.clientWidth, panel.clientHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.setClearColor(0x000000, 0);
        renderer.sortObjects = true;

        ringGroup = new THREE.Group();
        scene.add(ringGroup);

        createCards();
        computeDepthRange();
        initialized = true;
    }

    function createCards() {
        const sharedGeo = new THREE.PlaneGeometry(CONFIG.cardWidth, CONFIG.cardHeight, 1, 1);

        for (let i = 0; i < CONFIG.cardCount; i += 1) {
            const cardData = {
                baseAngle: i * ((Math.PI * 2) / CONFIG.cardCount),
                angleJitter: randomRange(-0.05, 0.05),
                radiusOffset: randomRange(-CONFIG.radiusOffsetRange, CONFIG.radiusOffsetRange),
                bandPhase: Math.random() * Math.PI * 2,
                depthBias: randomRange(-0.26, 0.26),
                trackOffset: randomRange(CONFIG.trackOffsetMin, CONFIG.trackOffsetMax),
                pullSpeed: randomRange(CONFIG.pullSpeedMin, CONFIG.pullSpeedMax),
                scaleBias: randomRange(0.95, 1.06),
                tiltX: randomRange(-0.035, 0.035),
                tiltY: randomRange(-0.04, 0.04),
                tiltZ: randomRange(-0.025, 0.025),
                mesh: null,
                trails: [],
            };

            const fallbackTexture = createFallbackTexture(i + 1);
            const assetImage = getVortexImage(i + 1);
            const hasInitialAssetTexture = assetImage.complete && assetImage.naturalWidth;
            const initialTexture = hasInitialAssetTexture
                ? createRoundedTexture(assetImage)
                : fallbackTexture;
            const mesh = new THREE.Mesh(sharedGeo, createCardMaterial(initialTexture, 1));
            mesh.frustumCulled = false;
            ringGroup.add(mesh);
            cardData.mesh = mesh;

            for (let t = 0; t < CONFIG.trailCount; t += 1) {
                const trail = new THREE.Mesh(sharedGeo, createCardMaterial(initialTexture, 0.2 - t * 0.05));
                trail.frustumCulled = false;
                ringGroup.add(trail);
                cardData.trails.push(trail);
            }

            cards.push(cardData);

            const applyAssetTexture = () => {
                if (!assetImage.naturalWidth && !assetImage.width) return;
                const rounded = createRoundedTexture(assetImage);
                setCardTexture(cardData, rounded);
            };

            if (!hasInitialAssetTexture) {
                const finalizeAssetTexture = () => {
                    if (assetImage.naturalWidth || assetImage.width) {
                        applyAssetTexture();
                    }
                };

                if (typeof assetImage.decode === 'function') {
                    assetImage.decode()
                        .then(finalizeAssetTexture)
                        .catch(() => {
                            requestAnimationFrame(finalizeAssetTexture);
                        });
                } else {
                    assetImage.addEventListener('load', finalizeAssetTexture, { once: true });
                }

                assetImage.addEventListener('error', () => {
                    console.error('[vortex] Failed to load local asset image:', makeImageUrl(i + 1));
                }, { once: true });
            }
        }
    }

    function createCardMaterial(texture, opacity) {
        return new THREE.MeshBasicMaterial({
            map: texture,
            transparent: true,
            opacity,
            depthWrite: false,
            side: THREE.DoubleSide,
        });
    }

    function setCardTexture(cardData, texture) {
        if (!cardData.mesh) return;
        const materials = [cardData.mesh.material, ...cardData.trails.map((trail) => trail.material)];
        const previousMaps = new Set(materials.map((mat) => mat.map).filter(Boolean));

        for (let i = 0; i < materials.length; i += 1) {
            materials[i].map = texture;
            materials[i].needsUpdate = true;
        }

        previousMaps.forEach((map) => {
            if (map !== texture) map.dispose();
        });
    }

    function getVortexProgress() {
        const start = panel.offsetTop;
        const height = panel.offsetHeight || window.innerHeight;
        return clamp((scrollRoot.scrollTop - start) / height, 0, 1);
    }

    function computePose(card, localT, angle, p, trailDepth = 0) {
        const t = clamp(localT, 0, 1);
        const depthT = clamp(t + smoothstep01(p) * 0.28, 0, 1);
        const baseRadius = THREE.MathUtils.lerp(CONFIG.startRadius, CONFIG.endRadius, depthT);
        const funnelScale = THREE.MathUtils.lerp(1.0, CONFIG.coreRadius, depthT);
        const radius = Math.max(
            0.03,
            baseRadius * funnelScale
            + card.radiusOffset * (1 - depthT)
            + Math.sin(card.bandPhase + t * 4.6) * CONFIG.bandThickness * (1 - depthT)
        );
        const x = CONFIG.vortexCenterX + Math.cos(angle) * radius;
        const y = CONFIG.vortexCenterY
            + Math.sin(angle) * radius * 0.68
            + Math.sin(card.bandPhase + t * 2.8) * CONFIG.bandYOffset * (1 - depthT);
        const z = THREE.MathUtils.lerp(CONFIG.zNear, CONFIG.zDeep, depthT)
            + card.depthBias * (1 - depthT)
            - trailDepth;

        return { x, y, z, localT: t, depthT };
    }

    function getCameraDepth(position) {
        viewVec.copy(position).applyMatrix4(camera.matrixWorldInverse);
        return -viewVec.z;
    }

    function computeDepthRange() {
        depthNear = CONFIG.depthNear;
        depthFar = CONFIG.depthFar;
    }

    function orientMesh(mesh, card, localT, p) {
        const tiltFactor = THREE.MathUtils.lerp(1, 0.72, localT) * THREE.MathUtils.lerp(1, 0.9, p);
        mesh.quaternion.copy(camera.quaternion);
        mesh.rotateY(card.tiltY * tiltFactor);
        mesh.rotateX(card.tiltX * tiltFactor);
        mesh.rotateZ(card.tiltZ * tiltFactor);
    }

    function applyStyle(mesh, card, p, localT, opacityFactor = 1, scaleFactor = 1, orderOffset = 0) {
        const depth = getCameraDepth(mesh.position);
        const depthT = clamp((depth - depthNear) / (depthFar - depthNear), 0, 1);
        const baseScale = THREE.MathUtils.lerp(CONFIG.scaleMax, CONFIG.scaleMin, depthT);
        const scrollScale = THREE.MathUtils.lerp(1, 0.86, Math.pow(p, 1.22));
        const localScale = THREE.MathUtils.lerp(1.04, 0.78, localT);
        const scale = clamp(
            baseScale * scrollScale * localScale * card.scaleBias * scaleFactor,
            CONFIG.scaleMin,
            CONFIG.scaleMax
        );
        const opacity = clamp(
            THREE.MathUtils.lerp(CONFIG.nearOpacity, CONFIG.farOpacity, depthT)
            * THREE.MathUtils.lerp(1.0, 0.86, Math.pow(p, 1.2))
            * THREE.MathUtils.lerp(1.0, 0.88, localT)
            * opacityFactor,
            0.015,
            1
        );
        const tint = THREE.MathUtils.lerp(1.0, 0.82, depthT);

        mesh.material.opacity = opacity;
        mesh.material.color.setRGB(tint, tint, tint);
        mesh.scale.setScalar(scale);
        mesh.renderOrder = Math.round((1 - depthT) * 10000 + (1 - localT) * 1000) + orderOffset;
    }

    function updateCard(card, p) {
        const pathT = clamp(card.trackOffset + p * card.pullSpeed, 0, 1);
        const rotation = p * CONFIG.rotationTurns * Math.PI * 2;
        const angle = card.baseAngle
            + rotation
            + pathT * CONFIG.spiralTurns * Math.PI * 2
            + card.angleJitter
            + interactionOffset * (1 - pathT * 0.8);
        const pose = computePose(card, pathT, angle, p, 0);

        card.mesh.position.set(pose.x, pose.y, pose.z);
        orientMesh(card.mesh, card, pose.localT, p);
        applyStyle(card.mesh, card, p, pose.localT, 1, 1, 50);

        for (let i = 0; i < card.trails.length; i += 1) {
            const trailT = clamp(pathT - CONFIG.trailStep * (i + 1), 0, 1);
            const trailAngle = card.baseAngle
                + rotation
                + trailT * CONFIG.spiralTurns * Math.PI * 2
                + card.angleJitter
                + interactionOffset * (1 - trailT * 0.8);
            const trailPose = computePose(card, trailT, trailAngle, p, (i + 1) * CONFIG.trailDepthStep);
            const trail = card.trails[i];
            trail.position.set(trailPose.x, trailPose.y, trailPose.z);
            orientMesh(trail, card, trailPose.localT, p);
            applyStyle(
                trail,
                card,
                p,
                trailPose.localT,
                0.3 - i * 0.06,
                0.96 - (i + 1) * 0.08,
                -(i + 1) * 14
            );
        }
    }

    function loop() {
        if (!running) return;

        const p = smoothstep01(getVortexProgress());
        if (!isDragging) {
            interactionTarget *= 0.9;
        }
        interactionOffset = THREE.MathUtils.lerp(interactionOffset, interactionTarget, 0.16);
        interactionOffset = clamp(interactionOffset, -CONFIG.maxInteractionOffset, CONFIG.maxInteractionOffset);

        for (let i = 0; i < cards.length; i += 1) {
            updateCard(cards[i], p);
        }

        renderer.render(scene, camera);
        rafId = requestAnimationFrame(loop);
    }

    function onPointerDown(event) {
        if (!running || event.target.closest('.nav,.cookie-banner,.theme-toggle')) return;
        isDragging = true;
        lastPointerX = event.clientX;
    }

    function onPointerMove(event) {
        if (!isDragging || !running) return;
        const dx = event.clientX - lastPointerX;
        lastPointerX = event.clientX;
        interactionTarget = clamp(
            interactionTarget + dx * CONFIG.dragSensitivity,
            -CONFIG.maxInteractionOffset,
            CONFIG.maxInteractionOffset
        );
    }

    function onPointerUp() {
        isDragging = false;
    }

    function onTouchStart(event) {
        if (!running || event.touches.length === 0) return;
        isDragging = true;
        lastPointerX = event.touches[0].clientX;
    }

    function onTouchMove(event) {
        if (!isDragging || !running || event.touches.length === 0) return;
        const dx = event.touches[0].clientX - lastPointerX;
        lastPointerX = event.touches[0].clientX;
        interactionTarget = clamp(
            interactionTarget + dx * CONFIG.dragSensitivity,
            -CONFIG.maxInteractionOffset,
            CONFIG.maxInteractionOffset
        );
    }

    function addListeners() {
        panel.addEventListener('pointerdown', onPointerDown);
        panel.addEventListener('pointermove', onPointerMove);
        panel.addEventListener('pointerup', onPointerUp);
        panel.addEventListener('pointerleave', onPointerUp);
        panel.addEventListener('touchstart', onTouchStart, { passive: true });
        panel.addEventListener('touchmove', onTouchMove, { passive: true });
        panel.addEventListener('touchend', onPointerUp, { passive: true });
    }

    function removeListeners() {
        panel.removeEventListener('pointerdown', onPointerDown);
        panel.removeEventListener('pointermove', onPointerMove);
        panel.removeEventListener('pointerup', onPointerUp);
        panel.removeEventListener('pointerleave', onPointerUp);
        panel.removeEventListener('touchstart', onTouchStart);
        panel.removeEventListener('touchmove', onTouchMove);
        panel.removeEventListener('touchend', onPointerUp);
    }

    function start() {
        if (!initialized) {
            try {
                init();
            } catch (error) {
                console.error('[vortex] failed to initialize:', error);
                ensureFallbackStars(fallback);
                return;
            }
        }

        if (running) return;
        running = true;
        addListeners();
        rafId = requestAnimationFrame(loop);
    }

    function stop() {
        running = false;
        isDragging = false;
        interactionTarget = 0;
        interactionOffset = 0;
        removeListeners();
        if (rafId) {
            cancelAnimationFrame(rafId);
            rafId = 0;
        }
    }

    function onResize() {
        if (!initialized) return;
        camera.aspect = panel.clientWidth / panel.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(panel.clientWidth, panel.clientHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        computeDepthRange();
    }

    return { start, stop, onResize };
}

function createFloatingSystem() {
    const panel = document.getElementById('floating');
    const stage = document.getElementById('floatingStage');
    const cardsLayer = panel.querySelector('.floating-cards');
    const items = Array.from(panel.querySelectorAll('.floating-item'));
    let running = false;
    let rafId = 0;

    function lerp(a, b, t) {
        return a + (b - a) * t;
    }

    function getFloatingProgress() {
        const viewport = scrollRoot.clientHeight || window.innerHeight;
        const start = panel.offsetTop - viewport * 0.42;
        const travel = viewport * 0.56;
        return clamp((scrollRoot.scrollTop - start) / travel, 0, 1);
    }

    function updateLanding() {
        const eased = smoothstep01(getFloatingProgress());
        const layerWidth = cardsLayer.clientWidth || panel.clientWidth;
        const layerHeight = cardsLayer.clientHeight || panel.clientHeight;
        const centerX = layerWidth * 0.5;
        const centerY = layerHeight * 0.52;

        for (let i = 0; i < items.length; i += 1) {
            const item = items[i];
            const finalCenterX = item.offsetLeft + item.offsetWidth * 0.5;
            const finalCenterY = item.offsetTop + item.offsetHeight * 0.5;
            const dx = centerX - finalCenterX;
            const dy = centerY - finalCenterY;
            const drift = 1 - eased;
            const translateX = dx * drift;
            const translateY = dy * drift;
            const scale = lerp(0.24, 1, eased);
            const opacity = lerp(0.08, 1, eased);

            item.style.transform = `translate3d(${translateX}px, ${translateY}px, 0) scale(${scale})`;
            item.style.opacity = `${opacity}`;
        }
    }

    function loop() {
        if (!running) return;
        updateLanding();
        rafId = requestAnimationFrame(loop);
    }

    function start() {
        if (running) return;
        running = true;
        panel.classList.add('active');
        stage.classList.add('active');
        updateLanding();
        rafId = requestAnimationFrame(loop);
    }

    function stop() {
        running = false;
        panel.classList.remove('active');
        stage.classList.remove('active');
        if (rafId) {
            cancelAnimationFrame(rafId);
            rafId = 0;
        }
    }

    function onResize() {
        updateLanding();
    }

    return { start, stop, onResize };
}

function createParticlesSystem() {
    const panel = document.getElementById('particles');
    const canvas = document.getElementById('particlesCanvas');
    const fallback = document.getElementById('particlesFallback');

    const CONFIG = {
        particleCount: window.innerWidth < 768 ? 900 : 1500,
        sphereRadius: 3.0,
        particleAlpha: 0.35,
        sphereOffsetY: 0.2,
        depthAlphaMultiplier: 0.6,
        twinkleSpeedMin: 0.15,
        twinkleSpeedMax: 0.45,
        autoRotateSpeed: 0.00005,
        dragDamping: 0.93,
        dragSensitivity: 0.002,
        maxRotationSpeed: 0.008,
    };

    let scene;
    let camera;
    let renderer;
    let points;
    let initialized = false;
    let running = false;
    let rafId = 0;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;
    let rotX = 0;
    let rotY = 0;
    let velX = 0;
    let velY = 0;
    let localTime = 0;

    const baseColors = [];
    const twinklePhases = [];
    const twinkleSpeeds = [];

    function init() {
        scene = new THREE.Scene();
        camera = new THREE.PerspectiveCamera(45, panel.clientWidth / panel.clientHeight, 0.1, 1000);
        camera.position.z = 9;

        renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: 'high-performance' });
        renderer.setSize(panel.clientWidth, panel.clientHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.setClearColor(0x000000, 0);

        const geometry = new THREE.BufferGeometry();
        const positions = [];
        const colors = [];

        for (let i = 0; i < CONFIG.particleCount; i += 1) {
            const phi = Math.acos(1 - 2 * (i + 0.5) / CONFIG.particleCount);
            const theta = Math.PI * (1 + Math.sqrt(5)) * i;

            const x = CONFIG.sphereRadius * Math.sin(phi) * Math.cos(theta);
            const y = CONFIG.sphereRadius * Math.sin(phi) * Math.sin(theta);
            const z = CONFIG.sphereRadius * Math.cos(phi);
            positions.push(x, y, z);

            const depth = (z + CONFIG.sphereRadius) / (CONFIG.sphereRadius * 2);
            const brightness = 0.5 + depth * CONFIG.depthAlphaMultiplier;
            baseColors.push(brightness, brightness, brightness);
            colors.push(brightness, brightness, brightness);

            twinklePhases.push(Math.random() * Math.PI * 2);
            twinkleSpeeds.push(CONFIG.twinkleSpeedMin + Math.random() * (CONFIG.twinkleSpeedMax - CONFIG.twinkleSpeedMin));
        }

        geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
        geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

        const material = new THREE.PointsMaterial({
            size: 0.05,
            sizeAttenuation: true,
            vertexColors: true,
            transparent: true,
            opacity: CONFIG.particleAlpha,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
        });

        points = new THREE.Points(geometry, material);
        points.position.y = CONFIG.sphereOffsetY;
        scene.add(points);
        initialized = true;
    }

    function loop() {
        if (!running) return;
        localTime += 0.016;

        const colorAttribute = points.geometry.attributes.color;
        const colors = colorAttribute.array;

        for (let i = 0; i < CONFIG.particleCount; i += 1) {
            const baseIndex = i * 3;
            const twinkle = 0.3 + 0.7 * Math.sin(localTime * twinkleSpeeds[i] + twinklePhases[i]);
            colors[baseIndex] = baseColors[baseIndex] * twinkle;
            colors[baseIndex + 1] = baseColors[baseIndex + 1] * twinkle;
            colors[baseIndex + 2] = baseColors[baseIndex + 2] * twinkle;
        }

        colorAttribute.needsUpdate = true;

        velX *= CONFIG.dragDamping;
        velY *= CONFIG.dragDamping;
        if (!isDragging) velY += CONFIG.autoRotateSpeed;

        rotX += velX;
        rotY += velY;

        points.rotation.x = rotX;
        points.rotation.y = rotY;

        renderer.render(scene, camera);
        rafId = requestAnimationFrame(loop);
    }

    function onPointerDown(event) {
        if (!running || event.target.closest('.nav')) return;
        isDragging = true;
        lastX = event.clientX;
        lastY = event.clientY;
    }

    function onPointerMove(event) {
        if (!isDragging || !running) return;
        const dx = event.clientX - lastX;
        const dy = event.clientY - lastY;
        velX = clamp(dy * CONFIG.dragSensitivity, -CONFIG.maxRotationSpeed, CONFIG.maxRotationSpeed);
        velY = clamp(dx * CONFIG.dragSensitivity, -CONFIG.maxRotationSpeed, CONFIG.maxRotationSpeed);
        lastX = event.clientX;
        lastY = event.clientY;
    }

    function onPointerUp() {
        isDragging = false;
    }

    function onTouchStart(event) {
        if (!running || event.touches.length === 0) return;
        isDragging = true;
        lastX = event.touches[0].clientX;
        lastY = event.touches[0].clientY;
    }

    function onTouchMove(event) {
        if (!isDragging || !running || event.touches.length === 0) return;
        const dx = event.touches[0].clientX - lastX;
        const dy = event.touches[0].clientY - lastY;
        velX = clamp(dy * CONFIG.dragSensitivity, -CONFIG.maxRotationSpeed, CONFIG.maxRotationSpeed);
        velY = clamp(dx * CONFIG.dragSensitivity, -CONFIG.maxRotationSpeed, CONFIG.maxRotationSpeed);
        lastX = event.touches[0].clientX;
        lastY = event.touches[0].clientY;
    }

    function addListeners() {
        panel.addEventListener('pointerdown', onPointerDown);
        panel.addEventListener('pointermove', onPointerMove);
        panel.addEventListener('pointerup', onPointerUp);
        panel.addEventListener('pointerleave', onPointerUp);
        panel.addEventListener('touchstart', onTouchStart, { passive: true });
        panel.addEventListener('touchmove', onTouchMove, { passive: true });
        panel.addEventListener('touchend', onPointerUp, { passive: true });
    }

    function removeListeners() {
        panel.removeEventListener('pointerdown', onPointerDown);
        panel.removeEventListener('pointermove', onPointerMove);
        panel.removeEventListener('pointerup', onPointerUp);
        panel.removeEventListener('pointerleave', onPointerUp);
        panel.removeEventListener('touchstart', onTouchStart);
        panel.removeEventListener('touchmove', onTouchMove);
        panel.removeEventListener('touchend', onPointerUp);
    }

    function start() {
        if (!initialized) {
            try {
                init();
            } catch (error) {
                console.error('[particles] failed to initialize:', error);
                ensureFallbackStars(fallback);
                return;
            }
        }

        if (running) return;
        running = true;
        addListeners();
        rafId = requestAnimationFrame(loop);
    }

    function stop() {
        running = false;
        isDragging = false;
        removeListeners();
        if (rafId) {
            cancelAnimationFrame(rafId);
            rafId = 0;
        }
    }

    function onResize() {
        if (!initialized) return;
        camera.aspect = panel.clientWidth / panel.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(panel.clientWidth, panel.clientHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }

    return { start, stop, onResize };
}

const systems = {
    vortex: createVortexSystem(),
    floating: createFloatingSystem(),
    particles: createParticlesSystem(),
};

let activeSection = null;

function activateSection(id) {
    if (!id || !systems[id] || activeSection === id) return;
    if (activeSection) systems[activeSection].stop();
    activeSection = id;
    systems[activeSection].start();

    const panels = document.querySelectorAll('.panel');
    for (let i = 0; i < panels.length; i += 1) {
        const panelId = panels[i].id;
        panels[i].classList.toggle('is-active', panelId === activeSection);
    }
}

function getActiveSectionFromScroll() {
    const y = scrollRoot.scrollTop;
    const floatingStart = document.getElementById('floating').offsetTop;
    const particlesStart = document.getElementById('particles').offsetTop;
    if (y >= particlesStart) return 'particles';
    if (y >= floatingStart) return 'floating';
    return 'vortex';
}

function syncActiveSection() {
    activateSection(getActiveSectionFromScroll());
}

scrollRoot.addEventListener('scroll', syncActiveSection, { passive: true });
syncActiveSection();

window.addEventListener('resize', () => {
    systems.vortex.onResize();
    systems.floating.onResize();
    systems.particles.onResize();
    syncActiveSection();
});
